function prng(seed){var a=seed>>>0||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var R=prng(62001);
var T0=Date.now();
var N=50;
var cap={cpu:1e12,gpu:Math.floor(N*0.6),acc:Math.floor(N*0.3)};
var used={cpu:0,gpu:0,acc:0},tot=0,base=0;
for(var i=0;i<N;i++){
  var c={cpu:10+Math.floor(R()*40),gpu:2+Math.floor(R()*15),acc:4+Math.floor(R()*20)};
  base+=c.cpu;
  var opts=[["cpu",c.cpu],["gpu",c.gpu],["acc",c.acc]].sort(function(a,b){return a[1]-b[1];});
  var dev=opts.find(function(o){return used[o[0]]<cap[o[0]];})||["cpu",c.cpu];
  used[dev[0]]++;tot+=dev[1];
}
console.log(JSON.stringify({id:"JAH-APX62-000001",ok:true,metrics:{ops:N,routed_cost:tot,all_cpu_baseline:base,saving_pct:+((1-tot/base)*100).toFixed(1),gpu_share:+(used.gpu/N).toFixed(2),acc_share:+(used.acc/N).toFixed(2)},ms:Date.now()-T0}));

